export const meta = {
  "slug": "heroicons-folder-open",
  "family": "heroicons",
  "name": "folder-open",
  "category": "Files",
  "motion": "file",
  "component": "createHeroiconsFolderOpenIcon"
};

export function createHeroiconsFolderOpenIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
